import{_ as t,c as s,o as i,j as e,a as n}from"./chunks/framework.Dnh4IO1K.js";const f=JSON.parse('{"title":"易緯乾元序制記〔漢〕鄭玄","description":"易緯乾元序制記 - 易緯乾元序制記〔漢〕鄭玄","frontmatter":{"title":"易緯乾元序制記〔漢〕鄭玄","description":"易緯乾元序制記 - 易緯乾元序制記〔漢〕鄭玄"},"headers":[],"relativePath":"classics/yiwei-qianyuan/001.md","filePath":"classics/yiwei-qianyuan/001.md"}'),r={name:"classics/yiwei-qianyuan/001.md"};function c(o,a,l,d,p,m){return i(),s("div",null,[...a[0]||(a[0]=[e("h1",{id:"易緯乾元序制記〔漢〕鄭玄",tabindex:"-1"},[n("易緯乾元序制記〔漢〕鄭玄 "),e("a",{class:"header-anchor",href:"#易緯乾元序制記〔漢〕鄭玄","aria-label":"Permalink to “易緯乾元序制記〔漢〕鄭玄”"},"​")],-1),e("p",null,"欽定四庫全書易緯乾元序制記 ​漢 鄭康成 注乾：元、亨、利、貞，道之用也。微明所接，德由備也。 ​道之用者，道之所起也備。乾為天，天豳微萌明之，道之所交也。德由是故備，謂經稱「元、亨、利、貞」也。文王比隆興始霸。 ​文王比德於乾之隆盛，謂其龍德長人以善，通其嘉會利貞之義。乾之以正，始霸四方，被江漢之上。伐崇，作靈臺，受赤雀丹書，稱王制命，示王意。 ​入戊午蔀二十九年，時有赤雀銜丹書而授之。鄭按：詩文王萹孔穎達正義引此文作是類謀，又引注稱 康成，今故據以為康成所注。又上文「興始霸」原本作「興起霸」，今亦據正義文改。序錄著卦科合謀 ​序錄，序王錄。著卦為六十四卦經科，設王令之卦。言道。深微幽虛恢。 ​深微幽虛，言純精無形。恢，大也。乾一言糺圖侯 ​此一言乾一守。糺猶正。侯，要終也。誤。按此注疑有脫。神爛天地塞， ​塞，滿。言乾之神明爛然滿天地之間也。文王用其不倦，武發修其質素，周公用其節序，三聖首乾德，各就「乾元利貞」，每遺夕惕若厲，懼後戒。 ​言三聖俱首乾德，而所有同異。「厚」當為亨。文王自朝至於日昃，不遑暇食，是乾乾不倦。武王承而行之，不敢有加，是乾之質素。周公制禮作樂，光文、武之業，是乾之節厚。六長人以善，嘉會通禮，利慎於義，幹事能正，六德靡悔，戰戰兢兢，三聖同之也。 按「節序」，據注應作「節候」。是類摘表甄符，應合命精克慎不合， ​甄絕。三聖俱知天命，能挺興衰之表象，及瑞之所應合，明天命精微之道，極慎不合道也。鉤效紀錄，興亡授度。 ​效，驗。言天能鉤驗五精，記其次第興亡，天人皆受法度。或為「授」。天子必思易，先知萬世，為國著柄。 ​柄，本要也。察之在，失之去。每雲天命在主，摽操 ​存在去亡。操行主，王之存亡。天命要，主之所行，用道興王也。六十四卦，各括精受節，以曆紀道。 ​括從絬精受節，謂各用事於諸月，以應紀明。天道，謂寒溫之節與藏者也。因象著命，取佐書，以州土之運次衡伍。 ​因象著命，謂敘其世數及名姓。取佐捉下輒皆以州土之運，以之卦於土，各有卦分相當，衡亭行為位之。 按此注疑有脫誤。一歲十二月三百六十五日四分度之一。 ​文宜言「四分日之一」。一日行一度，因言度餘二十。 ​餘，小余，即上「四分度之一」分數。四分一日以為八十分，二十為之。 ​四分一日以為大分則八十，以為小分則二十。小分四為一大分，消息十二月，月居六日七分，十二月居七十三日一百八十分居四分。 ​消息十二月，正居七十二日，通計餘分八十日四分，則七十三日八十分之四也。三公十二月，月居六日七分，十二月居七十三日一百八十分居四分。 ​按此下尚應有「九卿」一條，方合五德之數，蓋有脫文也。二十七大夫十二月，月居六日七分，十二月居七十三日一百八十分居四分。八百一十二諸侯十二月，月居六日七分，十二月居七十三日一百八十分居四分。合德之分。 ​五德，闢公、卿、大夫、諸侯也。三十日得三十五， ​此則五卦之餘分。三十盡十二月，六十卦餘分適四百二十分五日四分日一。 ​其法以餘分來乘卦，得四百二十，以八十餘已，則五日四分日一矣。此則方伯不與餘之也矣。闢卦溫氣不效，六卦陽物不生，土功起。 ​六卦謂泰卦、大壯也。夬、乾、姤也。盛陽時溫氣不效，故陽物不生，土功起也。○按注「姤」下尚當有「遁」卦，疑脫文。三卦陽氣不至，疾傷，日蝕既。 ​三卦謂泰、大壯、夬。此陽氣盛息，其候決溫，其氣不至，故闢憂疾，日蝕既日矣。六卦不至，震水湧。 ​其上三卦不效，後三卦又不效，於是陰乘其陽，故地震水湧也。寒氣不效，六卦不至，冬榮實物不成。夏寒傷生，冬溫傷成，日月不明，四時失序，萬物散去。 ​六卦謂否、觀、剝、坤、復、臨。盛陰用事，而寒氣不效，萬物冬榮，實物不成，其衝必有大寒，傷生物者也。闢卦七十三日，日分之四。常風亂先王之法度，常風。 ​常風，每卦用事，有暴風也。○按正文「法度」下「常風」二字疑衍。寒不時，所威不得其人。 ​謂春夏有寒效也。秋不霜，行春令，緩刑罰。冬不冰，行秋令，免有罪。春凍不解， ​亦謂溫效於秋初也。必有受命所亡。 ​謂受命之君所誅滅。奢侈過度，刑罰妄行，百姓急不足，困飢作奢。此受命所行， ​言王者雖有際會，安在其行之會？闢殺之法，十二卦常蒙三十六年殺，非受命所亡也。 ​常不清明，非受命所亡。言此君臣自相殺之候。○按「非受命所亡也」應作正文，「常不清明」以下應作注。原本以正文混作注，以注混作正文，今俱訂正。卦不至為三年。二卦不至為六年，三卦不至為九年，四卦不至為十二年，五卦不至為十五年，六卦不至為十八年，七卦不至為二十一年，八卦不至為二十四年。九卦不至為二十七年，十卦不至為三十年。十一卦不至為三十三年。十二卦不至為三十六年。 ​不至，謂溫不效，乃不清明也。卦始用事，象東風雨，象施於也。 ​按：「於」下疑有脫字。西方至，象作威也。南風，有罪也。 ​按：有罪上當有脫字。北風至，熟無罪也。 ​按：「熟」疑應作「殺」，蓋以殺變「煞」而誤者。東北為雨，西南為正，東南為溫，西北為寒， ​謂始用事也。文按：此注原本混入正， 今訂正。用事，東北為雨，西南為正也。東北南西皆風，東南溫，西北為寒， ​皆謂用事日也。○按：東北、南西二句，原本混作注，皆謂句混作正文，今俱訂正。觀六四知其正。此候及四位之人，非獨闢之。候卦要法，謹察卦用事日分數，當寒者寒，當暑者暑，當風者風，當雨者雨，此平法。 ​二為升氣，五為降氣，昇陽為陽，升陰馬寒，降陽為風，降陰為雨也。謹司六月中寒溫風雨，記其日與時，發時以驗方來，萬全不失一。 ​降效驗也。夏升降寒陰三過度，湧水為敗。夏昇陽降陽，溫三過度，降雨為敗。 ​謂六三、上六也。當微寒，過故為敗也。坎初，冬至，廣莫。震初，春分，明庶。離初，夏至景風。兌初，秋分，霜下。卦候到佔法 ​此四卦者，始效分至二十四氣之主，故候其初用事以佔之失。複姓角名宮，赤黃色，長八尺一寸，三十六世。臨姓商名宮，黃白色，長八尺三寸一分，七十二世。泰姓商名宮，黃白色，長七尺六寸，三十六世。 ​按隋書王劭傳稱坤電圖雲：「泰姓商名宮，黃色，長八尺，六十世。」與此不同。疑此即引坤靈圖原文，而傳寫互異者。大壯，姓商名角，蒼白色，長七尺三寸九分，百三十一世。右聖人受命，瑞應之至，聖人殺龍，聖人興起，河圖出之者。 ​按此與上下文不相屬，當有錯誤。據隋書王劭傳、馬驌繹史引坤靈圖文有「聖人受命，瑞應先於河，瑞應之至，聖人殺龍，龍不可殺，皆盛氣也」云云，疑即此文，而中有脫落耳。姤，姓角名商，蒼白色，長六尺三寸，二十八世。遁，姓宮名商，黃白色，長五尺九寸八分，五十六世。否，姓宮名商，黃白色，長五尺六寸一分，七十二世。觀，姓宮名角，蒼白色，長五尺三寸二分，百三十世。剝，姓商名宮，黃白色，長五尺九寸九分，百二十世。古君子得眾人所助，聖人興起必乾土，故大人動得中，君子受命法地蛇。 ​聖人興起必乾土之中者，言必擇土中而天下也。此在簡柝，預在此章之載。○按毛詩孔疏引坤靈圖雲：「法地之瑞，黃龍中流見於洛。」又繹史引坤靈圖雲：「君子得眾人之助，瑞應先見於陸。瑞應之至，君子法地，蛇不如龍，陸不如河。」與此文俱相合。疑自「古君子」以下，俱當為【【【坤靈圖】】】之文，而中有脫簡耳。乾姓商，名商，白色，享國百二十。坤姓商，名宮，黃色，享國百二十。震姓角名，蒼色，享國七十二。 ​按「名」下脫一字。巽姓角，名角，蒼色，享國六十四。離姓徵，名徵，赤色，享國六十四。兌姓商，名商，白色，享國六十四。坎姓羽，名羽，黑色，享國七十二。艮名宮，黃色，享國 ​七十二。按艮字下脫去二字。帝者，雒書居處法 ​亦宜有「右」字，以脫耳。○按【居處法】蓋亦雒書緯名，以上疑引其詞，而以此語題之，故云脫右字也。復始祖受命而王，子孫入其元百六歲，當陽旱不生， ​此天下故災之常也。王者受命，皆有災會，但言夏者，舉一隅小示之也。不生，物無生者也。災其惟以人軌年除軌數，筭盡則厄也。甲乙為飢，丙丁為旱，率如此也。○按據注則正文應有「夏」字，疑「復」即「夏」之訛也。賢子繼世而立，有災方來，豫畜而待之，此所謂轉禍為福。天災雖至，萬民無飢寒之色。 ​按以上疑亦坤靈圖註文而混錯在此者。冬溫傷藏，日月不明，四時失序，萬民散失，有受者常寒作藏也。霜 ​按此處原闕一字。深也，溫，賞予也。雨不時，特妄賞賜也。霜不時，殺無罪。風不時，令妄出也。冬不冰，行春令，免有罪也。春凍不解，行冬令，執無罪也。西風至，作威也。南風至，免有罪也。北風至，執無罪。 ​皆謂卦之不效逆四時。夏昇陽降溫，三過度，雨為敗。 ​謂九三、上九也。當徵而遇過度，其敗宜為風也。坎初六冬至，廣莫風，九二小寒，六三大寒，六四立春，條風，九五雨水，上六驚蟄。震初九春分，明庶風，六二清明，六三榖雨，九四立夏。溫風，六五小滿，上六芒種。離初九夏至。景風，六二小暑，九三大暑，九四立秋。涼風至，六五處暑，上九白露。兌初九秋分，閶闔風霜下，九二寒露，六三霜降，九四立冬，始冰。不周風，九五小雪，上六大雪也。 ​",-1)])])}const u=t(r,[["render",c]]);export{f as __pageData,u as default};
